def min_spots(n, H):
    def can_build_with_spots(spots):
        # Calculate the minimum number of sand packs needed to build the given number of spots
        total_sand_needed = 0
        for i in range(1, spots + 1):
            total_sand_needed += min(i, H)
        return total_sand_needed <= n

    # Binary search to find the minimum number of spots
    left, right = 1, n
    while left < right:
        mid = (left + right) // 2
        if can_build_with_spots(mid):
            right = mid
        else:
            left = mid + 1

    return left

