def min_spots_to_build_castle(n, H):
    def can_build_with_spots(spots):
        total_sand = 0
        for i in range(spots):
            if i == 0:
                total_sand += H
            else:
                total_sand += min(i + 1, n - total_sand)
            if total_sand > n:
                return False
        return total_sand == n

    left, right = 1, n
    while left < right:
        mid = (left + right) // 2
        if can_build_with_spots(mid):
            right = mid
        else:
            left = mid + 1
    return left

